// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Wallet} from "../src/Wallet.sol";

contract InvMutTest is Test {
    Wallet c;
    function setUp() public { c = new Wallet(); }
    function testFuzz_property(address sender, address to, uint256 depositAmount) public {
        vm.assume(sender != address(0));
        vm.assume(to != address(0));
        vm.assume(depositAmount > 0);

        vm.deal(sender, depositAmount);
        vm.prank(sender);
        c.deposit{value: depositAmount}();

        vm.prank(sender);
        bool ok_original;
        try c.migrateTo(to) { ok_original = true; } catch { ok_original = false; }

        assertTrue(!ok_original);
    }
}
